WITH lines AS (SELECT id, service, host, level, latency_ms, status_code, attr_key, attr_value FROM app_logs LATERAL VIEW OUTER EXPLODE(context) li AS attr_key, attr_value) SELECT host, level, service, COUNT(CASE WHEN host = 'h3' THEN 1 END) AS h3_count, CORR(status_code, latency_ms) AS corr_status_code_latency_ms, SIZE(COLLECT_SET(level)) AS num_levels, SORT_ARRAY(COLLECT_SET(attr_key)) AS attr_key_list, COUNT(DISTINCT host) AS distinct_hosts, MIN(status_code) AS min_status_code, GROUPING(host) AS grouping_level FROM lines GROUP BY GROUPING SETS ((host, level, service), (host, level), (host)) ORDER BY service DESC;
